func TestRetryTransport_RetriesWhenBodyIsReadSeeker(t *testing.T) {
	t.Parallel()

	var calls int
	var bodies []string
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		b, err := io.ReadAll(req.Body)
		if err != nil {
			return nil, err
		}
		bodies = append(bodies, string(b))
		status := 429
		if calls == 2 {
			status = 200
		}
		return &http.Response{
			StatusCode: status,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	rt := newRetryTransport(next, DefaultRetryPolicy(), retryTransportOptions{
		sleep: func(context.Context, time.Duration) error { return nil },
		now:   time.Now,
	})

	tmp, err := os.CreateTemp("", "retry-body-*")
	if err != nil {
		t.Fatalf("create temp: %v", err)
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.WriteString("file content"); err != nil {
		t.Fatalf("write temp: %v", err)
	}
	_ = tmp.Close()

	f, err := os.Open(tmp.Name())
	if err != nil {
		t.Fatalf("open temp: %v", err)
	}
	defer f.Close()

	req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.test", f)
	if req.GetBody != nil {
		t.Fatalf("expected req.GetBody to be nil for *os.File")
	}

	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = resp.Body.Close()

	if calls != 2 {
		t.Fatalf("expected 2 calls, got %d", calls)
	}
	if len(bodies) != 2 || bodies[0] != "file content" || bodies[1] != "file content" {
		t.Fatalf("expected file content on both attempts, got %#v", bodies)
	}
}

