func TestFilesService_Add_RetriesOnRateLimit(t *testing.T) {
	t.Parallel()

	var attempts int
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts: 3,
			BaseDelay:   1 * time.Millisecond,
			MaxDelay:    1 * time.Millisecond,
			Jitter:      func(d time.Duration) time.Duration { return d },
		},
	}, func(w http.ResponseWriter, r *http.Request) {
		attempts++
		if attempts == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"error":"rate limit exceeded"}`))
			return
		}

		contentType := r.Header.Get("Content-Type")
		_, params, err := mime.ParseMediaType(contentType)
		if err != nil {
			t.Fatalf("parse content type: %v", err)
		}
		mr := multipart.NewReader(r.Body, params["boundary"])
		part, err := mr.NextPart()
		if err != nil {
			t.Fatalf("next part: %v", err)
		}
		data, _ := io.ReadAll(part)
		if string(data) != "retry payload" {
			t.Fatalf("unexpected data on attempt %d: %q", attempts, string(data))
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":99,"name":"retry.txt"}}`))
	})

	file, err := client.Files.Add(context.Background(), "retry.txt", strings.NewReader("retry payload"))
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if attempts != 2 {
		t.Fatalf("expected 2 attempts, got %d", attempts)
	}
	if file.ID != 99 {
		t.Fatalf("unexpected file: %#v", file)
	}
}

