func TestFilesOptionsApplyQueryAndRequestOptions(t *testing.T) {
	t.Parallel()

	query := url.Values{"limit": []string{"7"}}
	cfg := newFilesOptions([]FilesOption{
		nil,
		WithFilesQuery(query),
		WithFilesRequestOptions(pipedrive.WithHeader("X-Test", "1")),
		WithFileDealID(10),
		WithFilePersonID(20),
		WithFileOrganizationID(30),
		WithFileProductID(40),
		WithFileActivityID(50),
		WithFileLeadID("lead-1"),
		WithFileProjectID(60),
	})

