		t.Fatalf("unexpected limit query: %q", got)
	}
	if *cfg.dealID != 10 || *cfg.personID != 20 || *cfg.orgID != 30 || *cfg.productID != 40 || *cfg.activityID != 50 || *cfg.leadID != "lead-1" || *cfg.projectID != 60 {
		t.Fatalf("unexpected file options: %#v", cfg)
